//! Read-only setup instructions generated by the same providers used by the CLI.

use std::path::Path;

use anyhow::Result;
use clap::ValueEnum;
use serde::Serialize;
use utoipa::ToSchema;

use super::providers::{AgentProvider, ConfigContext, provider};
use crate::config::SkillAgent;

#[derive(Serialize, ToSchema)]
pub struct AgentSetupResponse {
  pub endpoint: String,
  pub providers: Vec<AgentSetupProvider>,
}

#[derive(Serialize, ToSchema)]
pub struct AgentSetupProvider {
  pub id: String,
  pub label: &'static str,
  pub note: &'static str,
  pub install_link: Option<String>,
  pub project: AgentSetupScope,
  pub global: AgentSetupScope,
}

#[derive(Serialize, ToSchema)]
pub struct AgentSetupScope {
  pub command: String,
  pub skill_path: String,
  pub config_path: String,
  pub configuration: String,
}

pub fn catalog(endpoint: String) -> Result<AgentSetupResponse> {
  let providers = SkillAgent::value_variants()
    .iter()
    .filter(|agent| **agent != SkillAgent::Universal)
    .map(|agent| AgentSetupProvider::new(*agent, &endpoint))
    .collect::<Result<Vec<_>>>()?;
  Ok(AgentSetupResponse {
    endpoint,
    providers,
  })
}

impl AgentSetupProvider {
  fn new(agent: SkillAgent, endpoint: &str) -> Result<Self> {
    let adapter = provider(agent);
    let id = agent
      .to_possible_value()
      .expect("CLI agent has a name")
      .get_name()
      .to_string();
    Ok(Self {
      label: adapter.label(),
      note: adapter.note(),
      install_link: adapter.install_link(endpoint),
      project: scope(adapter, &id, endpoint, false)?,
      global: scope(adapter, &id, endpoint, true)?,
      id,
    })
  }
}

fn scope(
  adapter: &dyn AgentProvider,
  id: &str,
  endpoint: &str,
  global: bool,
) -> Result<AgentSetupScope> {
  let root = Path::new(if global { "~" } else { "" });
  let config = adapter.mcp_config(root, global, &ConfigContext::default())?;
  let scope = if global { " --global" } else { "" };
  // POSIX single-quote escaping: URLs can legally contain shell metacharacters.
  let quoted_endpoint = endpoint.replace('\'', "'\\''");
  Ok(AgentSetupScope {
    command: format!(
      "stove skills install --agent {id} --configure-mcp{scope} --mcp-url '{quoted_endpoint}'"
    ),
    skill_path: root.join(adapter.skill_directory()).display().to_string(),
    config_path: config.path.display().to_string(),
    configuration: config.format.merge(None, endpoint)?,
  })
}

#[cfg(test)]
mod tests {
  #[test]
  fn command_quotes_shell_metacharacters_as_a_single_argument() {
    let endpoint = "https://example.test/a'b/$(echo surprise);`echo surprise`/mcp";
    let catalog = super::catalog(endpoint.into()).unwrap();
    let command = &catalog.providers[0].project.command;
    // Replace only the executable with printf to inspect shell argument parsing.
    let script = command.replacen("stove ", "printf '%s\\n' ", 1);
    let output = std::process::Command::new("sh")
      .args(["-c", &script])
      .output()
      .unwrap();
    assert!(output.status.success());
    let stdout = String::from_utf8(output.stdout).unwrap();
    assert_eq!(stdout.lines().last(), Some(endpoint));
    assert_eq!(stdout.lines().count(), 7);
  }
}
